<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device375px, initial-scale=1.0">
    <title>登录 - 本地Demo</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
            background-color: #f5f5f5;
            min-height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .login-container {
            width: 375px;
            min-height: 100vh;
            background-color: #fff;
            padding: 60px 24px;
            display: flex;
            flex-direction: column;
        }

        @media (min-width: 376px) {
            .login-container {
                min-height: auto;
                border-radius: 8px;
                box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
                margin: 20px;
            }
        }

        .login-header {
            text-align: center;
            margin-bottom: 40px;
        }

        .login-header h1 {
            font-size: 24px;
            color: #333;
            font-weight: 600;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-group label {
            display: block;
            font-size: 14px;
            color: #333;
            margin-bottom: 8px;
            font-weight: 500;
        }

        .form-group input {
            width: 100%;
            height: 44px;
            padding: 0 16px;
            font-size: 14px;
            border: 1px solid #ddd;
            border-radius: 4px;
            outline: none;
            transition: border-color 0.2s;
        }

        .form-group input:focus {
            border-color: #1890ff;
        }

        .login-btn {
            width: 100%;
            height: 44px;
            background-color: #1890ff;
            color: #fff;
            font-size: 16px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            transition: background-color 0.2s;
            margin-top: 8px;
        }

        .login-btn:hover {
            background-color: #40a9ff;
        }

        .login-btn:active {
            background-color: #096dd9;
        }

        .error-message {
            color: #ff4d4f;
            font-size: 14px;
            margin-top: 8px;
            display: none;
        }

        .error-message.show {
            display: block;
        }

        /* Logged in state */
        .user-info {
            display: none;
            text-align: center;
        }

        .user-info.show {
            display: block;
        }

        .user-info .avatar {
            width: 80px;
            height: 80px;
            border-radius: 50%;
            background-color: #1890ff;
            color: #fff;
            font-size: 32px;
            display: flex;
            justify-content: center;
            align-items: center;
            margin: 0 auto 16px;
        }

        .user-info .email {
            font-size: 16px;
            color: #333;
            margin-bottom: 24px;
        }

        .logout-btn {
            width: 100%;
            height: 44px;
            background-color: #fff;
            color: #ff4d4f;
            font-size: 16px;
            border: 1px solid #ff4d4f;
            border-radius: 4px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .logout-btn:hover {
            background-color: #fff1f0;
        }

        .login-form {
            display: block;
        }

        .login-form.hidden {
            display: none;
        }

        .success-message {
            color: #52c41a;
            font-size: 14px;
            margin-top: 8px;
            display: none;
        }

        .success-message.show {
            display: block;
        }
    </style>
</head>
<body>
    <div class="login-container">
        <!-- Login Form -->
        <div class="login-form" id="loginForm">
            <div class="login-header">
                <h1>登录</h1>
            </div>

            <form id="form">
                <div class="form-group">
                    <label for="email">邮箱</label>
                    <input type="email" id="email" name="email" placeholder="请输入邮箱" required>
                </div>

                <div class="form-group">
                    <label for="password">密码</label>
                    <input type="password" id="password" name="password" placeholder="请输入密码" required>
                </div>

                <div class="error-message" id="errorMessage">邮箱或密码错误</div>
                <div class="success-message" id="successMessage">登录成功</div>

                <button type="submit" class="login-btn">登录</button>
            </form>
        </div>

        <!-- User Info (Logged in state) -->
        <div class="user-info" id="userInfo">
            <div class="login-header">
                <h1>欢迎回来</h1>
            </div>
            <div class="avatar" id="avatar">D</div>
            <div class="email" id="userEmail">demo@example.test</div>
            <button class="logout-btn" id="logoutBtn">退出登录</button>
        </div>
    </div>

    <script>
        // Fixed test account
        const FIXED_EMAIL = 'demo@example.test';
        const FIXED_PASSWORD = 'DemoPass2026';
        const STORAGE_KEY = 'login_status';

        // DOM elements
        const loginForm = document.getElementById('loginForm');
        const userInfo = document.getElementById('userInfo');
        const form = document.getElementById('form');
        const emailInput = document.getElementById('email');
        const passwordInput = document.getElementById('password');
        const errorMessage = document.getElementById('errorMessage');
        const successMessage = document.getElementById('successMessage');
        const logoutBtn = document.getElementById('logoutBtn');
        const userEmail = document.getElementById('userEmail');
        const avatar = document.getElementById('avatar');

        // Check if user is logged in on page load
        function checkLoginStatus() {
            const loginStatus = localStorage.getItem(STORAGE_KEY);
            if (loginStatus) {
                try {
                    const status = JSON.parse(loginStatus);
                    if (status.email === FIXED_EMAIL && status.loggedIn) {
                        showUserInfo(status.email);
                        return true;
                    }
                } catch (e) {
                    localStorage.removeItem(STORAGE_KEY);
                }
            }
            return false;
        }

        // Show user info (logged in state)
        function showUserInfo(email) {
            loginForm.classList.add('hidden');
            userInfo.classList.add('show');
            userEmail.textContent = email;
            avatar.textContent = email.charAt(0).toUpperCase();
        }

        // Show login form
        function showLoginForm() {
            userInfo.classList.remove('show');
            loginForm.classList.remove('hidden');
            errorMessage.classList.remove('show');
            successMessage.classList.remove('show');
            form.reset();
        }

        // Handle login
        function handleLogin(e) {
            e.preventDefault();

            const email = emailInput.value.trim();
            const password = passwordInput.value;

            // Clear previous messages
            errorMessage.classList.remove('show');
            successMessage.classList.remove('show');

            // Validate email format
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(email)) {
                errorMessage.textContent = '请输入有效的邮箱地址';
                errorMessage.classList.add('show');
                return;
            }

            // Validate credentials
            if (email === FIXED_EMAIL && password === FIXED_PASSWORD) {
                // Login success
                const status = {
                    email: email,
                    loggedIn: true,
                    loginTime: Date.now()
                };
                localStorage.setItem(STORAGE_KEY, JSON.stringify(status));

                successMessage.textContent = '登录成功';
                successMessage.classList.add('show');

                setTimeout(() => {
                    showUserInfo(email);
                }, 500);
            } else {
                // Login failed
                errorMessage.textContent = '邮箱或密码错误';
                errorMessage.classList.add('show');
            }
        }

        // Handle logout
        function handleLogout() {
            localStorage.removeItem(STORAGE_KEY);
            showLoginForm();
        }

        // Event listeners
        form.addEventListener('submit', handleLogin);
        logoutBtn.addEventListener('click', handleLogout);

        // Check login status on page load
        checkLoginStatus();
    </script>
</body>
</html>
